import{_ as n,o as t,c as s,a3 as i}from"./chunks/framework.B9qR_F1m.js";const c=JSON.parse('{"title":"Staffeln, Slots und Schlüssel","description":"","frontmatter":{},"headers":[],"relativePath":"gemeinsam/staffeln.md","filePath":"gemeinsam/staffeln.md"}'),r={name:"gemeinsam/staffeln.md"};function l(a,e,o,d,h,f){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="staffeln-slots-und-schlussel" tabindex="-1">Staffeln, Slots und Schlüssel <a class="header-anchor" href="#staffeln-slots-und-schlussel" aria-label="Permalink to &quot;Staffeln, Slots und Schlüssel&quot;">​</a></h1><p>Auf einem öffentlichen Shardwing-Server darf nicht jeder einfach Missionen ablegen, sonst ist er schnell voll. Deshalb bekommt jede <strong>Staffel</strong> vom Betreiber ein kleines Kontingent: <strong>Slots</strong>.</p><div class="info custom-block"><p class="custom-block-title">Kurz gesagt</p><ul><li><strong>Slot</strong> = eine Mission, die gerade auf dem Server liegt. Eine Staffel mit 2 Slots kann 2 Missionen gleichzeitig dort haben.</li><li>Wird eine Mission gelöscht oder läuft ab, ist ihr Slot <strong>sofort wieder frei</strong>.</li><li>Jede Staffel bekommt <strong>zwei Dinge</strong>: einen <strong>Schlüssel</strong> zum Hochladen und einen <strong>Staffel-Link</strong> zur Übersicht.</li></ul></div><table tabindex="0"><thead><tr><th></th><th>Was ist das?</th><th>Wer bekommt es?</th><th>Was kann man damit?</th></tr></thead><tbody><tr><td><strong>Schlüssel</strong></td><td>kurzer Code wie <code>K4P9-X2T7-M8QW</code></td><td>alle Mission Designer der Staffel</td><td>Missionen über <strong>Teilen</strong> auf den Server legen</td></tr><tr><td><strong>Staffel-Link</strong></td><td>Link zum Staffel-Panel</td><td>nur die Staffelführung</td><td>alle Missionen der Staffel sehen, als Designer öffnen, löschen, Schlüssel neu ausstellen</td></tr></tbody></table><p>Welche Rolle bist du?</p><ul><li><a href="#mission-hochladen">Ich baue Missionen und will eine hochladen</a></li><li><a href="#staffel-panel">Ich leite die Staffel und habe den Staffel-Link</a></li><li><a href="#fur-den-betreiber">Ich betreibe den Server</a></li></ul><h2 id="mission-hochladen" tabindex="-1">Mission hochladen <a class="header-anchor" href="#mission-hochladen" aria-label="Permalink to &quot;Mission hochladen&quot;">​</a></h2><p>Du brauchst nur den <strong>Schlüssel</strong> deiner Staffel. Den bekommst du von deiner Staffelführung, meist im Discord.</p><ol class="steps"><li>Mission in Shardwing öffnen, wie immer.</li><li>Oben auf <b>Teilen</b> klicken.</li><li>Beim ersten Mal den <b>Staffel-Schlüssel</b> eintippen oder einfügen. Groß- und Kleinschreibung und die Striche sind egal. Shardwing zeigt sofort, zu welcher Staffel er gehört und wie viele Slots frei sind.</li><li><b>Auf den Server legen</b> klicken. Fertig: Die Mission ist oben und du bist ihr Designer.</li></ol><p>Ab dem zweiten Mal ist es noch kürzer: Shardwing hat sich den Schlüssel gemerkt. Also <strong>Teilen → Auf den Server legen</strong>.</p><p>Im Teilen-Fenster siehst du die Slots als kleine Kästchen: gefüllt = belegt, leer = frei.</p><div class="warning custom-block"><p class="custom-block-title">„Alle Slots sind belegt“</p><p>Dann liegen schon so viele Missionen eurer Staffel auf dem Server, wie ihr haben dürft. Eine alte muss weg:</p><ul><li>Bist du Designer der alten Mission: öffnen, <strong>Übersicht → Paket → Server → Vom Server löschen …</strong></li><li>Sonst die Staffelführung fragen. Sie kann im Staffel-Panel jede Mission der Staffel löschen.</li></ul></div><p><strong>Anderer Schlüssel:</strong> Bist du in zwei Staffeln oder hat deine Staffel einen neuen Schlüssel bekommen, klick im Teilen-Fenster auf <strong>Anderer Schlüssel</strong> und gib den neuen ein.</p><p><strong>Desktop-App:</strong> genauso. Beim ersten Mal steht im Teilen-Fenster zusätzlich das Feld <strong>Server</strong>, z. B. <code>https://app.shardwing.de</code>.</p><h2 id="staffel-panel" tabindex="-1">Staffel-Panel <a class="header-anchor" href="#staffel-panel" aria-label="Permalink to &quot;Staffel-Panel&quot;">​</a></h2><p>Für die Staffelführung. Den <strong>Staffel-Link</strong> bekommst du vom Betreiber. Einmal öffnen genügt, danach steht <strong>Staffel-Panel</strong> im Shardwing-Menü. In der Desktop-App öffnest du den Link über <strong>Link öffnen</strong> (<kbd>⌘L</kbd> / <kbd>Strg+L</kbd>).</p><div class="danger custom-block"><p class="custom-block-title">Den Staffel-Link nicht weitergeben</p><p>Wer ihn hat, kommt als Designer in <strong>alle</strong> Missionen eurer Staffel. Deine Leute brauchen nur den Schlüssel.</p></div><p>Das Panel zeigt:</p><ul><li><strong>Slots:</strong> wie viele belegt sind, wie viele frei. Dazu, falls der Betreiber es eingestellt hat, Speicher und „gültig bis“.</li><li><strong>Schlüssel zum Hochladen:</strong><ul><li><strong>Für Discord kopieren</strong> – Schlüssel mit einer Zwei-Zeilen-Anleitung, fertig zum Einfügen.</li><li><strong>Nur den Schlüssel kopieren</strong></li><li><strong>Neuen Schlüssel ausstellen</strong> – wenn er zu weit herumgegangen ist. Der alte gilt dann sofort nicht mehr; Missionen auf dem Server bleiben, nur Hochladen geht dann nur noch mit dem neuen.</li></ul></li><li><strong>Eure Missionen:</strong><ul><li><strong>Öffnen</strong> – du planst als Designer mit.</li><li><strong>Designer-Link</strong> – kopieren, z. B. für einen zweiten Designer.</li><li><strong>Löschen</strong> – macht einen Slot frei. Planung, Plätze und Kneeboards sind dann weg. Die geplante .miz vorher speichern: <strong>Öffnen → Übersicht → Paket → Server → Aktuelle .miz</strong>.</li><li><strong>Mission hochladen …</strong> – eine .miz direkt hochladen, ohne sie vorher zu öffnen. Das ist dasselbe wie <strong>Teilen</strong>.</li></ul></li></ul><p>Wer das Panel einmal geöffnet hat, muss den Schlüssel im Teilen-Fenster nicht mehr eintippen. Shardwing nimmt ihn aus dem Panel.</p><h2 id="fur-den-betreiber" tabindex="-1">Für den Betreiber <a class="header-anchor" href="#fur-den-betreiber" aria-label="Permalink to &quot;Für den Betreiber&quot;">​</a></h2><p>In der <a href="./teilen#speicherdauer-und-loschen">Server-Verwaltung</a> (<code>https://dein-server/#/admin</code>, Master-Schlüssel) gibt es oben den Bereich <strong>Staffeln</strong>.</p><ol class="steps"><li><b>+ Neue Staffel</b>: Name (z. B. <i>JG 71 Virtual</i> oder <i>Tester Max</i>), <b>Slots</b> (Standard 2), optional <b>Speicher in MB</b> und <b>Gültig bis</b>. Leer heißt: keine Grenze.</li><li><b>Staffel anlegen</b>. Shardwing zeigt Staffel-Link und Schlüssel.</li><li><b>Nachricht kopieren</b> und der Staffelführung schicken, am besten als Direktnachricht. Die Nachricht enthält beide Teile und erklärt, was wohin gehört.</li></ol><p>In der Liste pro Staffel:</p><table tabindex="0"><thead><tr><th>Knopf</th><th>Was passiert</th></tr></thead><tbody><tr><td><strong>Nachricht</strong></td><td>Staffel-Link, Schlüssel und Anleitung kopieren (für die Staffelführung)</td></tr><tr><td><strong>Schlüssel</strong></td><td>nur Schlüssel und Anleitung kopieren (für Mitglieder)</td></tr><tr><td><strong>Panel-Link</strong></td><td>nur den Staffel-Link kopieren</td></tr><tr><td><strong>Ändern</strong></td><td>Name, Slots, Speicher, Gültig bis. Dort auch <strong>Neuer Panel-Link</strong> und <strong>Neuer Schlüssel</strong>, falls etwas in falsche Hände geraten ist.</td></tr><tr><td><strong>Sperren</strong></td><td>Keine neuen Missionen mehr, und in der Testphase öffnet der Schlüssel die App nicht mehr. Die Missionen auf dem Server bleiben und laufen normal weiter. <strong>Entsperren</strong> hebt das auf.</td></tr><tr><td><strong>Löschen</strong></td><td>Staffel-Link und Schlüssel gelten nicht mehr. Die Missionen der Staffel bleiben und gehören ab dann dir.</td></tr></tbody></table><ul><li><strong>Tester:</strong> eine normale Staffel, z. B. mit 1 Slot und einem Datum bei „Gültig bis“. Nach dem Datum kann sie nicht mehr hochladen, ihre Mission läuft normal ab.</li><li><strong>Nur App-Zugang:</strong> Knopf <strong>+ Nur App-Zugang</strong> legt einen Zugang mit 0 Slots an, z. B. für einen Tester oder Piloten, der nur planen soll. Der Schlüssel öffnet die App im Browser und am Desktop, hochladen kann er damit nichts. <strong>Nachricht</strong> kopiert Schlüssel, Browser-Link und Download der Desktop-App.</li><li><strong>Testphase:</strong> Auf einem Server mit Master-Schlüssel öffnet sich die Web-App nur mit Staffel-Schlüssel, Staffel-Link, Missionslink oder Master-Schlüssel, die Desktop-App einmalig mit einem Schlüssel (siehe <a href="/start/installieren#testphase-schlussel">Installieren</a>). Der Name der Staffel steht dann oben rechts als <strong>Beta · für …</strong> und klein auf jedem Kneeboard. Gesperrt, abgelaufen, gelöscht oder <strong>Neuer Schlüssel</strong>: Für diesen Schlüssel ist die App wieder zu. Die kopierten Nachrichten enthalten den Zugang schon. Mit <code>SHARDWING_APP_OPEN=1</code> ist die App wieder für alle offen.</li><li><strong>Missionsliste:</strong> In der Spalte <strong>Staffel</strong> steht, wer eine Mission hochgeladen hat. <em>Betreiber</em> heißt: mit dem Master-Schlüssel oder von einer gelöschten Staffel.</li><li><strong>Master-Schlüssel:</strong> Du selbst lädst wie bisher ohne Grenze hoch. Im Teilen-Fenster: <strong>Ich betreibe den Server (Master-Schlüssel)</strong>.</li><li><strong>Server-Grenze:</strong> Mit der Umgebungsvariable <code>SHARDWING_MAX_MISSIONS</code> nimmt der Server keine Staffel-Missionen mehr an, sobald so viele Missionen insgesamt auf ihm liegen.</li><li><strong>Notfall:</strong> <code>npm run admin -w @shardwing/server</code> auf dem Server listet alle Staffeln mit Staffel-Link und Schlüssel, dazu alle Missionen mit Designer-Link.</li></ul><p>Auf einem Server <strong>ohne</strong> Master-Schlüssel (z. B. lokal) braucht niemand einen Schlüssel. Das Teilen-Fenster fragt dann auch nicht danach.</p>',27)])])}const u=n(r,[["render",l]]);export{c as __pageData,u as default};
